function vocabWorkStartError(error,chooseAction){const detail=String(error?.code||'')+' '+String(error?.message||error||'Unbekannter Fehler'),blocked=/PERMISSION_DENIED|permission.denied|permission denied/i.test(detail),message=blocked?'Firebase blockiert das Anlegen des Warteraums. Prüfe, ob die Realtime-Database-Regeln für grammarRooms veröffentlicht wurden und du als Schiedsrichter angemeldet bist.':`Der Warteraum konnte nicht erstellt werden: ${String(error?.message||error||'Unbekannter Fehler')}`;app.innerHTML=card(`<h2>⚠️ Warteraum konnte nicht erstellt werden</h2><p class="error">${esc(message)}</p><p class="muted">Technische Meldung: ${esc(detail)}</p>`)+card(btn('Zur Battle-Auswahl',chooseAction,'alt'));status.textContent='';window.scrollTo({top:0,behavior:'smooth'});}
async function vocabWorkCreateRoom(kind,title,chooseAction){if(!adminLoggedIn||uid!==ADMIN_UID){loginForm();return;}if(!uid){msg('Anmeldung läuft noch. Bitte gleich erneut tippen.',true);return;}gbStop();const roomCode=String(Math.floor(100000+Math.random()*900000)),meta={hostUid:uid,kind,index:0,stage:'lobby',deadline:0,createdAt:Date.now()};gbChooseAction=chooseAction;gbCode=roomCode;gbRole='host';gbRoom={meta,slots:{}};gbRoomReady=true;gbRoomListenError=false;gbRender();try{await set(ref(db,`grammarRooms/${roomCode}/meta`),meta);if(gbCode===roomCode&&gbRole==='host')gbListen();}catch(e){if(gbCode===roomCode&&gbRole==='host')vocabWorkStartError(e,chooseAction);}}
